def solve(g):
    g=[row[:] for row in g]
    # seeds
    seeds={}
    lab,n=ndimage.label(np.array(g)!=0, structure=np.ones((3,3)))
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] not in (0,1): seeds[lab[r,c]]=g[r][c]
    out=[row[:] for row in g]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]==1:
                ok=True
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        rr,cc=r+dr,c+dc
                        if not(0<=rr<H and 0<=cc<W) or g[rr][cc]==0: ok=False
                if ok: out[r][c]=seeds[lab[r,c]]
    return out
